const initialTeams=Object.entries(teams).map(([name,t],i)=>({id:`team${i}`,name,division:divisions[i]||divisions[0],lead:['Maya Chen','Noah Williams','Sofia Patel','Avery Johnson','Ethan Brooks'][i],color:t.color,description:`${name} team objectives and execution.`,members:[['Maya Chen','Liam Scott'],['Noah Williams','Ivy Moore'],['Sofia Patel','Lucas Reed'],['Avery Johnson','Amelia Davis'],['Ethan Brooks','Emma Cole']][i]}));
const initialMembers=['Maya Chen','Liam Scott','Noah Williams','Ivy Moore','Sofia Patel','Lucas Reed','Avery Johnson','Amelia Davis','Ethan Brooks','Emma Cole'].map((name,i)=>({id:`member${i}`,name,email:`${name.toLowerCase().replace(' ','.')}@northstar.io`,role:i%2?'Contributor':['Chief Strategy Officer','VP Product','VP Growth','VP People','VP Revenue'][i/2]||'Team lead',status:'Active'}));
const initialCycles=[{id:'cy1',name:'Q3 2026',start:'2026-07-01',end:'2026-09-30',status:'Active',description:'Current quarterly execution cycle.'},{id:'cy2',name:'Q4 2026',start:'2026-10-01',end:'2026-12-31',status:'Planning',description:'Next quarter planning cycle.'},{id:'cy3',name:'Annual 2026',start:'2026-01-01',end:'2026-12-31',status:'Active',description:'Annual strategic priorities.'}];
const initialGoals = [
  {id:'g1',title:'Build the category-defining AI workspace',description:'Create a product experience customers cannot imagine working without.',team:'Company',division:'Corporate Strategy',owner:'Maya Chen',initials:'MC',progress:68,status:'On track',period:'Q3 2026',parentId:null,updated:'2h ago',keyResults:[{id:'kr11',title:'Reach 45% weekly active usage',value:72},{id:'kr12',title:'Increase NPS to 62',value:64},{id:'kr13',title:'Ship 3 AI workflow capabilities',value:67}],initiatives:[{id:'in11',title:'AI command center',status:'In progress'},{id:'in12',title:'Context-aware recommendations',status:'Planned'},{id:'in13',title:'Mobile workspace refresh',status:'In progress'}]},
  {id:'g2',title:'Deliver an exceptional activation experience',description:'Help every new team reach meaningful value in their first session.',team:'Product',division:'Product & Technology',owner:'Noah Williams',initials:'NW',progress:61,status:'On track',period:'Q3 2026',parentId:'g1',updated:'Yesterday',keyResults:[{id:'kr21',title:'Reduce time-to-value below 8 minutes',value:58},{id:'kr22',title:'Raise onboarding completion to 80%',value:64}],initiatives:[{id:'in21',title:'Guided workspace setup',status:'In progress'},{id:'in22',title:'Role-based templates',status:'Planned'},{id:'in23',title:'Activation analytics',status:'In progress'}]},
  {id:'g3',title:'Create a repeatable growth engine',description:'Build efficient, measurable acquisition loops across priority segments.',team:'Growth',division:'Marketing',owner:'Sofia Patel',initials:'SP',progress:44,status:'At risk',period:'Q3 2026',parentId:'g1',updated:'3h ago',keyResults:[{id:'kr31',title:'Generate 2,500 product-qualified leads',value:48},{id:'kr32',title:'Improve organic conversion by 25%',value:40}],initiatives:[{id:'in31',title:'Customer story program',status:'In progress'},{id:'in32',title:'SEO topic clusters',status:'In progress'},{id:'in33',title:'Partner launch playbook',status:'Planned'}]},
  {id:'g4',title:'Become the best place to do career-defining work',description:'Create an environment where ambitious people thrive and grow.',team:'People',division:'People & Culture',owner:'Avery Johnson',initials:'AJ',progress:76,status:'On track',period:'Q3 2026',parentId:null,updated:'Mon',keyResults:[{id:'kr41',title:'Reach 85% engagement score',value:82},{id:'kr42',title:'Fill 90% of key roles on time',value:70}],initiatives:[{id:'in41',title:'Manager excellence program',status:'In progress'},{id:'in42',title:'Career architecture rollout',status:'Planned'},{id:'in43',title:'Hiring bar calibration',status:'Done'}]},
  {id:'g5',title:'Scale leadership capability',description:'Equip every manager to lead with clarity, empathy, and accountability.',team:'People',division:'People & Culture',owner:'Amelia Davis',initials:'AD',progress:52,status:'At risk',period:'Q3 2026',parentId:'g4',updated:'Fri',keyResults:[{id:'kr51',title:'100% manager coaching completion',value:61},{id:'kr52',title:'Increase manager effectiveness to 4.3',value:43}],initiatives:[{id:'in51',title:'Monthly manager labs',status:'In progress'},{id:'in52',title:'Leadership 360 reviews',status:'Planned'}]},
  {id:'g6',title:'Accelerate enterprise expansion',description:'Win and grow strategic accounts with a focused commercial motion.',team:'Revenue',division:'Sales & Customer Success',owner:'Ethan Brooks',initials:'EB',progress:31,status:'Off track',period:'Q3 2026',parentId:null,updated:'4h ago',keyResults:[{id:'kr61',title:'Close $1.8M enterprise ARR',value:28},{id:'kr62',title:'Grow expansion pipeline to $4M',value:34}],initiatives:[{id:'in61',title:'Enterprise account pods',status:'In progress'},{id:'in62',title:'Executive sponsor program',status:'Planned'},{id:'in63',title:'Security readiness sprint',status:'In progress'}]}
];
